import java.util.Arrays;
import java.util.List;

public class StreamReduceExample {
    public static void main(String[] args) {
        List<Integer> numbers = Arrays.asList(1, 2, 3, 4, 5);

        // 1. Basic reduction returning an Optional
        int sumOptional = numbers.stream()
            .reduce((a, b) -> a + b)
            .orElse(0);

        // 2. Reduction with an explicit identity value
        int sumWithIdentity = numbers.stream()
            .reduce(0, Integer::sum);

        // 3. Generalized reduction with type transformation (String concatenation length)
        int totalCharacters = numbers.stream()
            .reduce(
                0,
                (subtotal, element) -> subtotal + element.toString().length(),
                Integer::sum
            );

        System.out.println("Sum: " + sumWithIdentity);
        System.out.println("Total Chars: " + totalCharacters);
    }
}
